{"content": "1|// DeskFlow Dashboard — QuadCardSlotResizer
2|// Shared height control for the 4-card grid slot on the dashboard.
3|
4|import { useState, useEffect, useRef, useCallback } from 'react';
5|import { motion } from 'motion/react';
6|import { ChevronUp, ChevronDown, GripHorizontal } from 'lucide-react';
7|
8|const STORAGE_KEY = 'df-dashboard-quad-height';
9|
10|export function QuadCardSlotResizer({
11|  defaultPx = 340,
12|  minPx = 220,
13|  maxPx = 700,
14|  onHeightChange,
15|}: {
16|  defaultPx?: number;
17|  minPx?: number;
18|  maxPx?: number;
19|  onHeightChange?: (px: number) => void;
20|}) {
21|  const [height, setHeight] = useState<number>(() => {
22|    try {
23|      const raw = localStorage.getItem(STORAGE_KEY);
24|      const parsed = raw ? parseInt(raw, 10) : defaultPx;
25|      if (Number.isFinite(parsed)) return Math.max(minPx, Math.min(maxPx, parsed));
26|    } catch {}
27|    return defaultPx;
28|  });
29|  const containerRef = useRef<HTMLDivElement | null>(null);
30|  const startYRef = useRef(0);
31|  const startHeightRef = useRef(height);
32|
33|  const applyHeight = useCallback(
34|    (next: number) => {
35|      setHeight(next);
36|      const node = containerRef.current;
37|      if (node) {
38|        node.style.setProperty('--dashboard-quad-slot-height', `${next}px`);
39|        node.style.height = `${next}px`;
40|      }
41|      onHeightChange?.(next);
42|      localStorage.setItem(STORAGE_KEY, `${next}`);
43|    },
44|    [onHeightChange]
45|  );
46|
47|  useEffect(() => {
48|    applyHeight(height);
49|  }, [applyHeight, height]);
50|
51|  const startDrag = (e: React.MouseEvent) => {
52|    e.preventDefault();
53|    startYRef.current = e.clientY;
54|    startHeightRef.current = height;
55|    document.body.classList.add('cursor-row-resize', 'select-none');
56|
57|    const handleMouseMove = (ev: MouseEvent) => {
58|      const delta = startYRef.current - ev.clientY;
59|      const next = Math.max(minPx, Math.min(maxPx, startHeightRef.current + delta));
60|      applyHeight(next);
61|    };
62|
63|    const handleMouseUp = () => {
64|      document.removeEventListener('mousemove', handleMouseMove);
65|      document.removeEventListener('mouseup', handleMouseUp);
66|      document.body.classList.remove('cursor-row-resize', 'select-none');
67|    };
68|
69|    document.addEventListener('mousemove', handleMouseMove);
70|    document.addEventListener('mouseup', handleMouseUp);
71|  };
72|
73|  return (
74|    <div ref={containerRef} className="flex flex-col">
75|      <div
76|        className="flex items-center justify-center gap-1 pt-2 pb-1 select-none"
77|        title="Drag to adjust the height of the 4-card dashboard row"
78|      >
79|        <motion.div
80|          className="flex items-center gap-1 px-2 py-1 rounded-md bg-zinc-800/30 border border-zinc-700/30 hover:border-zinc-600/50 hover:bg-zinc-800/50 transition-all text-zinc-500 hover:text-zinc-300 cursor-row-resize"
81|          onMouseDown={startDrag}
82|          whileHover={{ scale: 1.02 }}
83|          whileTap={{ scale: 0.98 }}
84|        >
85|          <GripHorizontal size={10} />
86|          <span className="text-[10px] font-mono">{height}px</span>
87|          <ChevronUp size={10} />
88|          <ChevronDown size={10} />
89|        </motion.div>
90|      </div>
91|    </div>
92|  );
93|}
