{"content": "1|// ============================================================
2|// DeskFlow Dashboard — CardHeightResizer
3|// Draggable handle to adjust the max-height of card list containers
4|// in real-time by updating CSS custom properties on the card element
5|// ============================================================
6|
7|import { useState, useRef, useEffect } from 'react';
8|import { motion } from 'motion/react';
9|import { Maximize2, ChevronDown, ChevronUp } from 'lucide-react';
10|import type { CSSProperties } from 'react';
11|
12|interface CardHeightResizerProps {
13|  /** CSS variable name to adjust, e.g. "--dashboard-card-list-max-height" */
14|  cssVar: string;
15|  /** Default pixel value for the variable */
16|  defaultPx?: number;
17|  /** Minimum pixel value */
18|  minPx?: number;
19|  /** Maximum pixel value */
20|  maxPx?: number;
21|  /** Optional label shown on the handle */
22|  label?: string;
23|}
24|
25|export function CardHeightResizer({
26|  cssVar,
27|  defaultPx = 96,
28|  minPx = 60,
29|  maxPx = 300,
30|  label = 'Resize',
31|}: CardHeightResizerProps) {
32|  const [isDragging, setIsDragging] = useState(false);
33|  const [isCollapsed, setIsCollapsed] = useState(false);
34|  const startXRef = useRef(0);
35|  const startYRef = useRef(0);
36|  const currentHeightRef = useRef(defaultPx);
37|
38|  // Initialize the CSS variable on mount
39|  useEffect(() => {
40|    const root = document.documentElement;
41|    const currentValue = getComputedStyle(root).getPropertyValue(cssVar).trim();
42|    if (currentValue) {
43|      currentHeightRef.current = parseInt(currentValue) || defaultPx;
44|    }
45|    root.style.setProperty(cssVar, `${defaultPx}px`);
46|  }, [cssVar, defaultPx]);
47|
48|  const startDrag = (e: React.MouseEvent) => {
49|    e.preventDefault();
50|    setIsDragging(true);
51|    startXRef.current = e.clientX;
52|    startYRef.current = e.clientY;
53|    currentHeightRef.current = parseInt(
54|      getComputedStyle(document.documentElement).getPropertyValue(cssVar) || `${defaultPx}`
55|    ) || defaultPx;
56|  };
57|
58|  useEffect(() => {
59|    if (!isDragging) return;
60|
61|    const handleMouseMove = (e: MouseEvent) => {
62|      const deltaY = startYRef.current - e.clientY; // dragging up = bigger
63|      const newHeight = Math.max(minPx, Math.min(maxPx, currentHeightRef.current + deltaY));
64|      document.documentElement.style.setProperty(cssVar, `${newHeight}px`);
65|    };
66|
67|    const handleMouseUp = () => {
68|      setIsDragging(false);
69|    };
70|
71|    document.addEventListener('mousemove', handleMouseMove);
72|    document.addEventListener('mouseup', handleMouseUp);
73|
74|    return () => {
75|      document.removeEventListener('mousemove', handleMouseMove);
76|      document.removeEventListener('mouseup', handleMouseUp);
77|    };
78|  }, [isDragging, cssVar, minPx, maxPx, defaultPx]);
79|
80|  const toggleCollapse = () => {
81|    const root = document.documentElement;
82|    if (isCollapsed) {
83|      root.style.setProperty(cssVar, `${currentHeightRef.current}px`);
84|    } else {
85|      root.style.setProperty(cssVar, '0px');
86|    }
87|    setIsCollapsed(!isCollapsed);
88|  };
89|
90|  if (isCollapsed) return null;
91|
92|  return (
93|    <div
94|      className="flex items-center gap-1 cursor-ns-resize opacity-40 hover:opacity-80 transition-opacity py-1"
95|      onMouseDown={startDrag}
96|      title={`Drag to adjust ${label} height`}
97|    >
98|      <motion.div
99|        className="flex items-center gap-1 text-[9px] text-zinc-500"
100|        style={{ pointerEvents: isDragging ? 'none' : 'auto' }}
101|      >
102|        <Maximize2 size={10} />
103|        <span>{label}</span>
104|        <ChevronUp size={10} />
105|      </motion.div>
106|    </div>
107|  );
108|}
109|
110|interface CardHeightToggleProps {
111|  cssVar: string;
112|  defaultPx?: number;
113|  minPx?: number;
114|  maxPx?: number;
115|  label?: string;
116|}
117|
118|export function CardHeightToggle({
119|  cssVar,
120|  defaultPx = 96,
121|  minPx = 60,
122|  maxPx = 300,
123|  label = 'Height',
124|}: CardHeightToggleProps) {
125|  const [level, setLevel] = useState<'compact' | 'medium' | 'tall'>('medium');
126|
127|  const levels = [
128|    { key: 'compact' as const, px: 60, label: 'Compact' },
129|    { key: 'medium' as const, px: 96, label: 'Medium' },
130|    { key: 'tall' as const, px: 160, label: 'Tall' },
131|  ];
132|
133|  const setHeight = (px: number) => {
134|    document.documentElement.style.setProperty(cssVar, `${px}px`);
135|  };
136|
137|  const cycle = () => {
138|    const next = levels[(levels.findIndex(l => l.key === level) + 1) % levels.length];
139|    setLevel(next.key);
140|    setHeight(next.px);
141|  };
142|
143|  const current = levels.find(l => l.key === level) || levels[1];
144|
145|  return (
