19|
20|export function ResizableHeightHandle({
21|  cardId,
22|  defaultHeight = 96,
23|  minHeight = 48,
24|  maxHeight = 300,
25|  onHeightChange,
26|}: ResizableHeightHandleProps) {
27|  const [height, setHeight] = useState(defaultHeight);
28|  const startYRef = useRef(0);
29|  const startHeightRef = useRef(defaultHeight);
30|  const draggingRef = useRef(false);
31|
32|  const handleMouseDown = (e: React.MouseEvent) => {
33|    e.preventDefault();
34|    e.stopPropagation();
35|    draggingRef.current = true;
36|    startYRef.current = e.clientY;
37|    startHeightRef.current = height;
38|    document.addEventListener('mousemove', handleMouseMove);
39|    document.addEventListener('mouseup', handleMouseUp);
40|    document.body.classList.add('cursor-row-resize', 'select-none');
41|  };
42|
43|  const handleMouseMove = (e: MouseEvent) => {
44|    if (!draggingRef.current) return;
45|    const delta = startYRef.current - e.clientY;
46|    const newHeight = Math.max(minHeight, Math.min(maxHeight, startHeightRef.current + delta));
47|    setHeight(newHeight);
48|    onHeightChange?.(newHeight);
49|
50|    // Apply to the target list container
51|    const target = document.querySelector(`[data-card-list="${cardId}"]`);
52|    if (target) {
53|      (target as HTMLElement).style.maxHeight = newHeight + 'px';
54|    }
55|  };
56|
57|  const handleMouseUp = () => {
58|    draggingRef.current = false;
59|    document.removeEventListener('mousemove', handleMouseMove);
60|    document.removeEventListener('mouseup', handleMouseUp);
61|    document.body.classList.remove('cursor-row-resize', 'select-none');
62|  };
63|
64|  useEffect(() => {
65|    return () => {
66|      document.removeEventListener('mousemove', handleMouseMove);
67|      document.removeEventListener('mouseup', handleMouseUp);
68|      document.body.classList.remove('cursor-row-resize', 'select-none');
69|    };
70|  }, []);
71|
72|  return (
73|    <motion.div
74|      className="shrink-0 flex items-center justify-center py-1 cursor-row-resize group"
75|      onMouseDown={handleMouseDown}
76|      onMouseEnter={() => document.body.classList.add('cursor-row-resize')}
