// Shared height control for the 4-card dashboard grid row.
// Rendered as a drag handle ABOVE the grid (NOT a grid child), so it
// never steals a column from the cards. It sets an explicit height on
// the grid container so all 4 cards stretch to the same height at once.

import { useState, useEffect, useRef, useCallback } from 'react';
import { motion } from 'motion/react';
import { ChevronUp, ChevronDown, GripHorizontal } from 'lucide-react';

const STORAGE_KEY = 'df-dashboard-quad-height';

export function QuadCardSlotResizer({
  defaultPx = 340,
  minPx = 220,
  maxPx = 700,
  onHeightChange,
  targetRef,
}: {
  defaultPx?: number;
  minPx?: number;
  maxPx?: number;
  onHeightChange?: (px: number) => void;
  /** Ref to the grid container whose height we control. */
  targetRef?: React.RefObject<HTMLDivElement>;
}) {
  const [height, setHeight] = useState<number>(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      const parsed = raw ? parseInt(raw, 10) : defaultPx;
      if (Number.isFinite(parsed)) return Math.max(minPx, Math.min(maxPx, parsed));
    } catch {}
    return defaultPx;
  });

  const startYRef = useRef(0);
  const startHeightRef = useRef(height);

  const applyHeight = useCallback(
    (next: number) => {
      setHeight(next);
      const node = targetRef?.current;
      if (node) {
        // Apply explicit height so the grid row (and thus all 4 cards)
        // stretch to the same value at once.
        node.style.setProperty('--dashboard-quad-slot-height', `${next}px`);
        node.style.height = `${next}px`;
      }
      onHeightChange?.(next);
      localStorage.setItem(STORAGE_KEY, `${next}`);
    },
    [onHeightChange, targetRef]
  );

  // Hydrate the container on mount / target swap.
  useEffect(() => {
    applyHeight(height);
  }, [applyHeight, height]);

  const startDrag = (e: React.MouseEvent) => {
    e.preventDefault();
    startYRef.current = e.clientY;
    startHeightRef.current = height;
    document.body.classList.add('cursor-row-resize', 'select-none');

    const handleMouseMove = (ev: MouseEvent) => {
      const delta = startYRef.current - ev.clientY; // drag up = taller
      const next = Math.max(minPx, Math.min(maxPx, startHeightRef.current + delta));
      applyHeight(next);
    };

    const handleMouseUp = () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.classList.remove('cursor-row-resize', 'select-none');
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <motion.div
      className="flex items-center justify-center gap-1 pt-2 pb-1 select-none"
      title="Drag to adjust the height of the 4-card dashboard row (all 4 cards at once)"
    >
      <motion.div
        className="flex items-center gap-1 px-2 py-1 rounded-md bg-zinc-800/30 border border-zinc-700/30 hover:border-zinc-600/50 hover:bg-zinc-800/50 transition-all text-zinc-500 hover:text-zinc-300 cursor-row-resize"
        onMouseDown={startDrag}
        whileHover={{ scale: 1.02 }}
        whileTap={{ scale: 0.98 }}
      >
        <GripHorizontal size={10} />
        <span className="text-[10px] font-mono">{height}px</span>
        <ChevronUp size={10} />
        <ChevronDown size={10} />
      </motion.div>
    </motion.div>
  );
}
"}

