{"content": "// DeskFlow Dashboard — VCalendar
// Styled calendar (react-day-picker v10) matching the 21st.dev v-calendar-5
// aesthetic with month/year dropdown selects and chevron nav buttons.
// Used as the date selector for the DeadlinesCard "add upcoming" form.

import { useState, useMemo } from 'react';
import { DayPicker, type Matcher, type Direction } from 'react-day-picker';
import {
  ChevronLeft,
  ChevronRight,
  ChevronsUpDown,
} from 'lucide-react';
import { useLocale, type Locale } from 'date-fns/locale';
import { format } from 'date-fns';

import { cn } from '@/lib/utils';
import {
  Select,
  SelectItem,
  SelectTrigger,
} from '../ui/select';

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

function YearSelect({
  value,
  onChange,
  min,
  max,
}: {
  value: number;
  onChange: (year: number) => void;
  min?: number;
  max?: number;
}) {
  const start = min ?? new Date().getFullYear() - 10;
  const end = max ?? new Date().getFullYear() + 10;
  const years: number[] = [];
  for (let y = start; y <= end; y++) years.push(y);

  return (
    <Select
      valueLabel={y => String(y)}
      value={String(value)}
      onValueChange={v => onChange(Number(v))}
    >
      <SelectTrigger className="border-zinc-700 bg-zinc-800 text-zinc-200 focus:ring-indigo-500/20 px-2 py-1 text-xs sm:text-sm h-7">
        <span className="truncate">{value}</span>
        <ChevronsUpDown className="ml-1 h-3 w-3 text-zinc-400" />
      </SelectTrigger>
      {years.map(y => (
        <SelectItem key={y} value={String(y)}>{y}</SelectItem>
      ))}
    </Select>
  );
}

function MonthSelect({
  value,
  onChange,
}: {
  value: number;
  onChange: (month: number) => void;
}) {
  return (
    <Select
      valueLabel={m => MONTHS[Number(m)]}
      value={String(value)}
      onValueChange={v => onChange(Number(v))}
    >
      <SelectTrigger className="border-zinc-700 bg-zinc-800 text-zinc-200 focus:ring-indigo-500/20 px-2 py-1 text-xs sm:text-sm h-7 w-[110px]">
        <span className="truncate">{MONTHS[value]}</span>
        <ChevronsUpDown className="ml-1 h-3 w-3 text-zinc-400" />
      </SelectTrigger>
      {MONTHS.map((m, i) => (
        <SelectItem key={i} value={String(i)}>{m}</SelectItem>
      ))}
    </Select>
  );
}

interface VCalendarProps {
  mode?: 'single' | 'multiple' | 'range';
  selected?: Date | Date[] | undefined;
  onSelect?: (date: Date | Date[] | undefined) => void;
  defaultMonth?: Date;
  minDate?: Date;
  maxDate?: Date;
  disabled?: Matcher | Matcher[];
  locale?: Locale;
  initialFocus?: boolean;
  className?: string;
}

export function VCalendar({
  mode = 'single',
  selected,
  onSelect,
  defaultMonth,
  minDate,
  maxDate,
  disabled,
  locale: localeProp,
  initialFocus = false,
  className,
}: VCalendarProps) {
  const { locale: localeFn } = useLocale();
  const locale = localeProp ?? localeFn;

  // React-day-picker uses the Caption to render month/year dropdowns.
  // We track the displayed month to sync the dropdowns and allow the user
  // to flip months/years via the selects.
  const [month, setMonth] = useState<Date>(
    defaultMonth ?? (selected as Date) ?? new Date()
  );

  const selectedArray: Date[] = useMemo(() => {
    if (!selected) return [];
    return Array.isArray(selected) ? selected : [selected];
  }, [selected]);

  const handleMonthsChange = (next: Date | undefined) => {
    const m = next ?? month;
    setMonth(m);
    if (onSelect && mode === 'single') {
      // Keep the previously selected date; only the displayed month changes here.
    }
  };

  const handleYearChange = (year: number) => {
    const newMonth = new Date(month);
    newMonth.setFullYear(year);
    setMonth(newMonth);
    if (onSelect && mode === 'single' && selected) {
      const d = selected as Date;
      const updated = new Date(d);
      updated.setFullYear(year);
      onSelect(updated);
    }
  };

  const handleMonthChange = (m: number) => {
    const newMonth = new Date(month);
    newMonth.setMonth(m);
    setMonth(newMonth);
    if (onSelect && mode === 'single' && selected) {
      const d = selected as Date;
      const updated = new Date(d);
      updated.setMonth(m);
      // If the day doesn't exist in the target month (e.g. day 31 -> Feb),
      // clamp to the last valid day.
      if (updated.getMonth() !== m) {
        updated.setDate(0);
      }
      onSelect(updated);
    }
  };

  // Build nav button handlers that step month/year
  const prevMonth = () => {
    const nm = new Date(month);
    nm.setMonth(nm.getMonth() - 1);
    setMonth(nm);
  };
  const nextMonth = () => {
    const nm = new Date(month);
    nm.setMonth(nm.getMonth() + 1);
    setMonth(nm);
  };

  return (
    <DayPicker
      mode={mode as any}
      month={month}
      onMonthChange={handleMonthsChange}
      selected={selectedArray.length > 0 ? selectedArray : undefined}
      onSelect={onSelect as any}
      defaultMonth={defaultMonth}
      minDate={minDate}
      maxDate={maxDate}
      disabled={disabled as any}
      locale={locale}
      initialFocus={initialFocus}
      showOutsideDays
      className={cn(
        'rdp-root w-full',
        '[--cell-size:theme(spacing.10)] sm:[--cell-size:theme(spacing.9)]',
        className
      )}
      classNames={{
        months: 'flex flex-col sm:flex-row space-y-4 sm:space-x-4 sm:space-y-0',
        month: 'space-y-4',
        caption:
          'flex justify-center pt-1 relative items-center mb-2',
        caption_between:
          'flex items-center justify-between',
        caption_label:
          'text-sm font-medium text-zinc-300',
        nav: 'absolute top-1 left-1 right-1 flex items-center justify-between z-1 pointer-events-none',
        nav_button: cn(
          'pointer-events-auto relative flex size-(--cell-size) text-base sm:text-sm items-center justify-center rounded-lg text-foreground not-in-data-selected:hover:bg-accent disabled:pointer-events-none disabled:opacity-64'
        ),
        nav_button_previous:
          'absolute left-1',
        nav_button_next:
          'absolute right-1',
        table: 'w-full border-collapse',
        head_row: 'flex',
        head_cell:
          'size-(--cell-size) text-[10px] font-medium text-zinc-500 uppercase',
        row: 'flex w-full mt-2 items-stretch',
        cell: cn(
          'size-(--cell-size) text-center text-sm relative p-0 m-0.5',
          '[&:has([aria-selected])]:bg-accent first:[&:has([aria-selected])]:rounded-l-lg last:[&:has([aria-selected])]:rounded-r-lg'
        ),
        day: cn(
          'relative flex size-(--cell-size) text-base sm:text-sm items-center justify-center rounded-lg text-foreground not-in-data-selected:hover:bg-accent disabled:pointer-events-none disabled:opacity-64 aria-selected:opacity-100 hover:bg-zinc-800 hover:text-white text-zinc-300 data-selected:bg-primary data-selected:text-primary-foreground focus:Ring-2 focus:ring-ring focus:ring-2 focus:ring-offset-2 focus:outline-none transition-colors'
        ),
        range: 'bg-accent',
        selected:
          'bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground focus:bg-primary focus:text-primary-foreground',
        today: "bg-accent text-accent-foreground",
        outside:
          "text-muted-foreground/50 aria-selected:bg-transparent data-selected:text-primary-foreground",
        disabled: "text-zinc-500 opacity-50",
        hidden: "invisible",
        month_caption: 'hidden',
      }}
      components={{
        IconLeft: () => (
          <ChevronLeft className="h-4 w-4 sm:h-3.5 sm:w-3.5" />
        ),
        IconRight: () => (
          <ChevronRight className="h-4 w-4 sm:h-3.5 sm:w-3.5" />
        ),
        MonthCaption: ({ month }) => (
          <div className="flex items-center justify-center gap-1 w-full">
            <MonthSelect
              value={month.getMonth()}
              onChange={handleMonthChange}
            />
            <YearSelect
              value={month.getFullYear()}
              onChange={handleYearChange}
            />
          </div>
        ),
      }}
    >
      {/* Nav buttons overlaid */}
      <button
        type="button"
        aria-label="Previous month"
        onClick={prevMonth}
        className="absolute left-1 top-1 z-10 flex size-(--cell-size) text-base sm:text-sm items-center justify-center rounded-lg not-in-data-selected:hover:bg-accent text-zinc-400 hover:text-white disabled:opacity-50"
      >
        <ChevronLeft className="h-4 w-4 sm:h-3.5 sm:w-3.5" />
      </button>
      <button
        type="button"
        aria-label="Next month"
        onClick={nextMonth}
        className="absolute right-1 top-1 z-10 flex size-(--cell-size) text-base sm:text-sm items-center justify-center rounded-lg not-in-data-selected:hover:bg-accent text-zinc-400 hover:text-white disabled:opacity-50"
      >
        <ChevronRight className="h-4 w-4 sm:h-3.5 sm:w-3.5" />
      </button>
    </DayPicker>
  );
}
