{"content": "1|import type { ExternalActivity, ExternalSession } from "@/types/external";
2|
3|export type Gap = {
4|  id: string;
5|  start: Date;
6|  end: Date;
7|  duration_seconds: number;
8|};
9|
10|export type GapSegment = {
11|  id: string;
12|  activityId: string | null;
13|  minutes: number;
14|};
15|
16|export type TrackedInterval = {
17|  start: Date;
18|  end: Date;
19|};
20|
21|export function createId(prefix = "id"): string {
22|  return `${prefix}_${Math.random().toString(36).slice(2, 10)}_${Date.now().toString(36)}`;
23|}
24|
25|export function mergeTrackedIntervals(
26|  sessions: ExternalSession[],
27|  rangeStart: Date,
28|  rangeEnd: Date
29|): TrackedInterval[] {
30|  const intervals: TrackedInterval[] = [];
31|
32|  for (const session of sessions) {
33|    const start = new Date(session.started_at);
34|    const end = new Date(session.ended_at);
35|
36|    const clampedStart = start < rangeStart ? rangeStart : start;
37|    const clampedEnd = end > rangeEnd ? rangeEnd : end;
38|
39|    if (clampedEnd <= clampedStart) continue;
40|
41|    intervals.push({
42|      start: clampedStart,
43|      end: clampedEnd,
44|    });
45|  }
46|
47|  intervals.sort((a, b) => a.start.getTime() - b.start.getTime());
48|
49|  const merged: TrackedInterval[] = [];
50|
51|  for (const interval of intervals) {
52|    const last = merged[merged.length - 1];
53|
54|    if (!last) {
55|      merged.push({ ...interval });
56|      continue;
57|    }
58|
59|    if (interval.start <= last.end) {
60|      last.end = interval.end > last.end ? interval.end : last.end;
61|    } else {
62|      merged.push({ ...interval });
63|    }
64|  }
65|
66|  return merged;
67|}
