69|export function detectGaps(
70|  sessions: ExternalSession[],
71|  rangeStart: Date,
72|  rangeEnd: Date,
73|  minGapMinutes = 5
74|): Gap[] {
75|  if (rangeEnd <= rangeStart) return [];
76|
77|  const merged = mergeTrackedIntervals(sessions, rangeStart, rangeEnd);
78|  const gaps: Gap[] = [];
79|
80|  let cursor = rangeStart;
81|
82|  for (const interval of merged) {
83|    if (interval.start > cursor) {
84|      const durationSeconds = Math.round((interval.start.getTime() - cursor.getTime()) / 1000);
85|
86|      if (durationSeconds >= minGapMinutes * 60) {
87|        gaps.push({
88|          id: createId("gap"),
89|          start: new Date(cursor),
90|          end: new Date(interval.start),
91|          duration_seconds: durationSeconds,
92|        });
93|      }
94|    }
95|
96|    cursor = interval.end > cursor ? interval.end : cursor;
97|  }
98|
99|  if (rangeEnd > cursor) {
100|    const durationSeconds = Math.round((rangeEnd.getTime() - cursor.getTime()) / 1000);
101|
102|    if (durationSeconds >= minGapMinutes * 60) {
103|      gaps.push({
