115|export function mergeAdjacentSegments(segments: GapSegment[]): GapSegment[] {
116|  const merged: GapSegment[] = [];
117|
118|  for (const segment of segments) {
119|    if (!segment.activityId || segment.minutes <= 0) continue;
120|
121|    const last = merged[merged.length - 1];
122|
123|    if (last && last.activityId === segment.activityId) {
124|      last.minutes += segment.minutes;
125|    } else {
126|      merged.push({ ...segment });
127|    }
128|  }
129|
130|  return merged;
