133|/**
134| * Scales a composition of segments (built against one reference gap) to fit a
135| * different gap's duration, preserving relative proportions. Used by the
136| * multi-gap fill flow: the user composes once, every selected gap receives the
137| * same relative composition scaled to its own length.
138| *
139| * Unassigned segments (activityId null) are dropped — they carry no time.
140| * Each scaled segment is clamped to a minimum of 1 minute; the rounding
141| * remainder is added to the last segment. fillGapWithSegments clips anything
142| * that would overshoot a very small gap's end.
143| */
144|export function scaleSegmentsToGap(
145|  segments: GapSegment[],
146|  targetSeconds: number
147|): GapSegment[] {
148|  const active = segments.filter((segment) => segment.activityId);
149|  if (!active.length) return [];
150|
151|  const targetMinutes = Math.max(1, Math.round(targetSeconds / 60));
152|  const referenceMinutes = active.reduce(
153|    (sum, segment) => sum + Math.max(1, segment.minutes),
154|    0
155|  );
156|  if (referenceMinutes <= 0) {
157|    return active.map((segment) => ({ ...segment, minutes: 1 }));
158|  }
159|
160|  let assigned = 0;
161|
162|  return active.map((segment, index) => {
163|    if (index === active.length - 1) {
164|      return { ...segment, minutes: Math.max(1, targetMinutes - assigned) };
165|    }
166|
167|    const minutes = Math.max(
168|      1,
169|      Math.floor((Math.max(1, segment.minutes) * targetMinutes) / referenceMinutes)
170|    );
171|    assigned += minutes;
172|
173|    return { ...segment, minutes };
174|  });
175|}
