177|export async function fillGapWithSegments(
178|  gap: Gap,
179|  segments: GapSegment[],
180|  addExternalTime: (
181|    activityId: string,
182|    minutes: number,
183|    startedAt: string,
184|    endedAt: string
185|  ) => Promise<void>
186|): Promise<void> {
187|  const merged = mergeAdjacentSegments(segments);
188|  if (!merged.length) return;
189|
190|  let cursor = new Date(gap.start);
191|  const gapEnd = new Date(gap.end);
192|
193|  for (const segment of merged) {
194|    if (!segment.activityId) continue;
195|
196|    const minutes = Math.max(1, Math.round(segment.minutes));
197|    const end = new Date(cursor.getTime() + minutes * 60_000);
198|
199|    if (end > gapEnd) break;
200|
201|    await addExternalTime(
202|      segment.activityId,
203|      minutes,
204|      cursor.toISOString(),
205|      end.toISOString()
206|    );
207|
208|    cursor = end;
209|  }
210|}
