212|export function suggestGapActivities(
213|  gap: Gap,
214|  sessions: ExternalSession[],
215|  activities: ExternalActivity[],
216|  limit = 4
217|): ExternalActivity[] {
218|  const gapHour = gap.start.getHours();
219|  const gapWeekday = gap.start.getDay();
220|  const now = Date.now();
221|
222|  const scores = new Map<string, number>();
223|
224|  const activityByName = new Map(activities.map((activity) => [activity.name, activity]));
225|
226|  for (const session of sessions) {
227|    const activity = activityByName.get(session.activity_name);
228|    if (!activity) continue;
229|    if (activity.type === "sleep") continue;
230|
231|    const start = new Date(session.started_at);
232|    const hourDistance = Math.abs(start.getHours() - gapHour);
233|    const hourScore = hourDistance <= 2 ? 3 : hourDistance <= 4 ? 1 : 0;
234|    const weekdayScore = start.getDay() === gapWeekday ? 2 : 0;
235|
236|    const ageDays = Math.max(0, (now - start.getTime()) / 86_400_000);
237|    const recencyBoost = Math.max(0.25, 1 - ageDays / 45);
238|
239|    const durationHours = Math.max(0.1, session.duration_seconds / 3600);
240|    const score = durationHours * (1 + hourScore + weekdayScore) * recencyBoost;
241|
242|    scores.set(activity.id, (scores.get(activity.id) ?? 0) + score);
243|  }
244|
245|  const sorted = [...scores.entries()].sort((a, b) => b[1] - a[1]);
246|
247|  const suggested = sorted
248|    .map(([activityId]) => activities.find((activity) => activity.id === activityId))
249|    .filter(Boolean) as ExternalActivity[];
250|
251|  if (suggested.length >= limit) {
252|    return suggested.slice(0, limit);
253|  }
254|
255|  const fallback = activities
256|    .filter((activity) => activity.type !== "sleep")
257|    .filter((activity) => !suggested.some((s) => s.id === activity.id));
258|
259|  return [...suggested, ...fallback].slice(0, limit);
