3|export interface CellKey { day: number; hour: number }
4|export const cellId = (day: number, hour: number): string => day + ':' + hour
5|
6|export const jsDayToRow = (jsDay: number): number => (jsDay === 0 ? 6 : jsDay - 1)
7|
8|export function isoToCell(iso: string): CellKey {
9|  const d = new Date(iso)
10|  return { day: jsDayToRow(d.getDay()), hour: d.getHours() }
11|}
12|
13|export interface GapCellCoverage { day: number; hour: number; coveredSeconds: number }
14|
15|export function gapToCells(gap: Gap): GapCellCoverage[] {
16|  const out: GapCellCoverage[] = []
17|  let cursor = new Date(gap.start).getTime()
18|  const end = new Date(gap.end).getTime()
19|  let guard = 0
20|  while (cursor < end && guard < 48) {
21|    guard += 1
22|    const d = new Date(cursor)
23|    const hourStart = new Date(d.getFullYear(), d.getMonth(), d.getDate(), d.getHours(), 0, 0, 0).getTime()
24|    const hourEnd = hourStart + 3600 * 1000
25|    const chunkEnd = Math.min(end, hourEnd)
26|    out.push({ day: jsDayToRow(d.getDay()), hour: d.getHours(), coveredSeconds: (chunkEnd - cursor) / 1000 })
27|    cursor = chunkEnd
28|  }
29|  return out
30|}
31|
32|export function buildGapMap(gaps: Gap[]): Map<string, number> {
33|  const m = new Map<string, number>()
34|  for (const g of gaps) {
35|    for (const c of gapToCells(g)) {
36|      const k = cellId(c.day, c.hour)
37|      m.set(k, (m.get(k) ?? 0) + c.coveredSeconds)
38|    }
39|  }
40|  return m
41|}
