4|import type { ExternalActivity, ExternalSession } from "@/types/external";
5|import {
6|  suggestGapActivities,
7|  type Gap,
8|} from "@/lib/external/gaps";
9|
10|export type Timeframe = "day" | "week" | "month" | "all";
11|
12|const TIMEFRAME_OPTIONS: { key: Timeframe; label: string }[] = [
13|  { key: "day", label: "Day" },
14|  { key: "week", label: "Week" },
15|  { key: "month", label: "Month" },
16|  { key: "all", label: "All Time" },
17|];
18|
19|function formatTime(date: Date): string {
20|  return date.toLocaleTimeString([], {
21|    hour: "2-digit",
22|    minute: "2-digit",
23|  });
24|}
25|
26|function formatMinutes(minutes: number): string {
27|  if (minutes >= 60) {
28|    const h = minutes / 60;
29|    return `${h % 1 === 0 ? h.toFixed(0) : h.toFixed(1)}h`;
30|  }
31|
32|  return `${minutes}m`;
33|}
34|
35|// Splits multi-day gaps (backend merges untracked spans across day boundaries
36|// into one contiguous gap) into one per-day segment, clipped at local midnights
37|// so each calendar day renders as its own row with its own duration.
38|function splitGapByDay(gap: Gap): Gap[] {
39|  const start = new Date(gap.start);
40|  const end = new Date(gap.end);
41|
42|  if (start.toDateString() === end.toDateString()) return [gap];
43|
44|  const result: Gap[] = [];
45|  let dayStart = new Date(start.getFullYear(), start.getMonth(), start.getDate());
46|
47|  while (dayStart.getTime() < end.getTime()) {
48|    const nextDay = new Date(dayStart);
49|    nextDay.setDate(nextDay.getDate() + 1);
50|
51|    const segStart = start.getTime() > dayStart.getTime() ? start : dayStart;
52|    const segEnd = end.getTime() < nextDay.getTime() ? end : nextDay;
53|
54|    if (segEnd.getTime() > segStart.getTime()) {
55|      result.push({
56|        id: `${gap.id}|${segStart.getTime()}-${segEnd.getTime()}`,
57|        start: segStart,
58|        end: segEnd,
59|        duration_seconds: Math.max(
60|          0,
61|          Math.round((segEnd.getTime() - segStart.getTime()) / 1000)
62|        ),
63|      });
64|    }
65|    dayStart = nextDay;
66|  }
67|
68|  return result.length > 0 ? result : [gap];
69|}
70|
71|function formatDay(date: Date): string {
72|  const today = new Date();
73|  const startOfToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
74|  const startOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate());
75|  const diffDays = Math.round((startOfDay.getTime() - startOfToday.getTime()) / 86_400_000);
76|
77|  if (diffDays === 0) return "Today";
78|  if (diffDays === -1) return "Yesterday";
79|  if (diffDays === 1) return "Tomorrow";
80|
81|  return date.toLocaleDateString([], {
82|    weekday: "short",
83|    month: "short",
84|    day: "numeric",
85|  });
86|}
