192|      byDay.set(key, dayGaps);
193|    }
194|
195|    return Array.from(byDay.entries()).map(([key, dayGaps]) => ({
196|      id: key,
197|      label: formatDay(dayGaps[0].start),
198|      gaps: dayGaps,
199|    }));
200|  }, [allGaps]);
201|
202|  return (
203|    <AnimatePresence>
204|      {open && (
